import pandas as pd

def clean(df):
    df = df.copy()
    # fix label variants in Category
    if 'Category' in df.columns:
        df['Category'] = df['Category'].astype(str).str.strip()
    # fix Price text numbers like "$300.00"
    if 'Price' in df.columns:
        df['Price'] = df['Price'].astype(str).str.replace(r'[\$,]', '', regex=True).str.strip()
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    # ensure Quantity numeric and positive
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
        df.loc[df['Quantity'] < 0, 'Quantity'] = df.loc[df['Quantity'] < 0, 'Quantity'].abs()
    # remove exact duplicate rows
    df = df.drop_duplicates()
    return df

def answer(df):
    dfc = clean(df)
    sums = dfc.groupby('Region', dropna=False)['Quantity'].sum()
    out = {}
    for region, val in sums.items():
        if pd.isna(region):
            continue
        out[region] = int(val) if pd.notna(val) else 0
    return out
